function nodeEditor(node, index, nodes = []) {
  const options = nodeOptions(nodes, "");
  return `<article class="graph-node graph-node-${attr(node.type)}" data-graph-node>
    <div class="graph-node-head"><strong>${text(node.label || node.id)}</strong><span>${text(node.type)}</span><button type="button" data-graph-action="delete:${attr(node.id)}">×</button></div>
    <label>ID<input data-node-field="id" value="${attr(node.id)}"></label>
    <label>Type<select data-node-field="type">${typeOptions(node.type)}</select></label>
    <label>Label<input data-node-field="label" value="${attr(node.label)}"></label>
    <label class="node-match">Contains / Regex pattern<input data-node-field="match" value="${attr(node.match)}"></label>
    <label class="node-prompt">Prompt<textarea data-node-field="prompt" rows="4">${text(node.prompt)}</textarea></label>
    <label>Archive tag<input data-node-field="archiveTag" value="${attr(node.archiveTag)}"></label>
    <label>On true<select data-node-field="onTrue">${nodeOptions(nodes, node.onTrue)}</select></label>
    <label>On false<select data-node-field="onFalse">${nodeOptions(nodes, node.onFalse)}</select></label>
    <label>Next<select data-node-field="next">${nodeOptions(nodes, node.next)}</select></label>
    <label class="graph-toggle"><input data-node-field="negate" type="checkbox" ${node.negate ? "checked" : ""}> Negate condition</label>
    <p>${text(describeNode(node))}</p>
  </article>`;
}

function nodeOptions(nodes = [], selected = "") {
  return `<option value="">—</option>${nodes.map(node => `<option value="${attr(node.id)}" ${node.id === selected ? "selected" : ""}>${text(node.id)}</option>`).join("")}`;
}

function typeOptions(selected = "send") {
  return ["condition", "send", "archive", "stop"].map(type => `<option value="${type}" ${type === selected ? "selected" : ""}>${type}</option>`).join("");
}
